using System;
using System.Collections.Generic;

namespace KaiAosNotifyClient
{
    internal static class ClientUiStrings
    {
        private static string _lang = "en";
        private static readonly Dictionary<string, Dictionary<string, string>> Maps =
            new Dictionary<string, Dictionary<string, string>>();

        static ClientUiStrings()
        {
            Maps["en"] = En();
            Maps["ro"] = Ro();
            Maps["de"] = De();
            Maps["fr"] = Fr();
            Maps["es"] = Es();
            Maps["it"] = It();
            Maps["da"] = Da();
            Maps["cs"] = Cs();
            Maps["nl"] = Nl();
            Maps["pl"] = Pl();
            Maps["pt"] = Pt();
            Maps["sv"] = Sv();
            Maps["no"] = No();
            Maps["ru"] = Ru();
            Maps["tr"] = Tr();
            Maps["ja"] = Ja();
            Maps["ko"] = Ko();
            Maps["zh"] = Zh();
            Maps["th"] = Th();
        }

        public static string Language { get { return _lang; } }

        public static void SetLanguage(string code)
        {
            if (string.IsNullOrWhiteSpace(code)) code = "en";
            _lang = code.Trim().ToLowerInvariant();
            if (_lang == "en-gb" || _lang == "en-us") _lang = "en";
            if (!Maps.ContainsKey(_lang)) _lang = "en";
        }

        public static string T(string key)
        {
            Dictionary<string, string> map;
            string v;
            if (Maps.TryGetValue(_lang, out map) && map != null && map.TryGetValue(key, out v))
                return v;
            if (Maps.TryGetValue("en", out map) && map != null && map.TryGetValue(key, out v))
                return v;
            return key;
        }

